//
//	client.Initiative.Create().
//	    OnConflict(sql.ResolveWithIgnore()).
//	    Exec(ctx)
func (u *InitiativeUpsertOne) Ignore() *InitiativeUpsertOne {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *InitiativeUpsertOne) DoNothing() *InitiativeUpsertOne {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the InitiativeCreate.OnConflict
// documentation for more info.
func (u *InitiativeUpsertOne) Update(set func(*InitiativeUpsert)) *InitiativeUpsertOne {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&InitiativeUpsert{UpdateSet: update})
	}))
	return u
}

